using System;
using System.Collections.Generic;
using System.Data;
using System.Globalization;
using System.Linq;
using System.Web.Script.Serialization;
using SimsObject;
using WebGlobal;

namespace InformationWeb.Dashboards.Lib
{
    public partial class BookBorrowStatisticsDashboard : ControlBase
    {
        private const string SP_STATISTICS = "LIB_BorrowBook_Online_Statistics";

        private bool CheckPermission()
        {
            if (User == null)
            {
                MessageManager.ShowMessage(Page, "Bạn chưa đăng nhập hệ thống!");
                this.Visible = false;
                return false;
            }
            return true;
        }

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!CheckPermission())
                return;

            if (!IsPostBack)
            {
                txtFromDate.Text = DateTime.Now.AddMonths(-5).ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
                txtToDate.Text = DateTime.Now.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
                LoadData();
            }
        }

        protected void btnFilter_Click(object sender, EventArgs e)
        {
            LoadData();
            udpDashboard.Update();
        }

        private void LoadData()
        {
            SIM_Student obj = new SIM_Student();
            DateTime? fromDate = ParseDateInput(txtFromDate.Text);
            DateTime? toDate = ParseDateInput(txtToDate.Text);

            object objStudentId = DBNull.Value;
            object objLoginName = DBNull.Value;
            if (User != null && !string.IsNullOrEmpty(User.UserName))
                objLoginName = User.UserName;

            DataTable dt = obj.GetDataTable(
                SP_STATISTICS,
                "@FromDate", fromDate.HasValue ? (object)fromDate.Value.Date : DBNull.Value,
                "@ToDate", toDate.HasValue ? (object)toDate.Value.Date : DBNull.Value,
                "@StudentID", objStudentId,
                "@LoginName", objLoginName
            );

            if (dt == null)
            {
                MessageManager.ShowMessage(Page, "Việc tải dữ liệu thống kê bị lỗi!");
                return;
            }

            BindSummary(dt);
            BindCharts(dt);
            BindRangeDescription(fromDate, toDate);
        }

        private void BindSummary(DataTable dt)
        {
            int total = dt.Rows.Count;
            int approved = dt.AsEnumerable().Count(IsApprovedForStatistics);
            int borrowing = dt.AsEnumerable().Count(IsCurrentlyBorrowedNotReturned);
            int overdue = dt.AsEnumerable().Count(IsOverdueNotReturned);

            litTotalRequest.Text = total.ToString("N0", CultureInfo.InvariantCulture);
            litApproved.Text = approved.ToString("N0", CultureInfo.InvariantCulture);
            litBorrowing.Text = borrowing.ToString("N0", CultureInfo.InvariantCulture);
            litOverdue.Text = overdue.ToString("N0", CultureInfo.InvariantCulture);
        }

        private void BindCharts(DataTable dt)
        {
            JavaScriptSerializer serializer = new JavaScriptSerializer();

            List<IGrouping<object, DateTime>> monthlyData = dt.AsEnumerable()
                .Select(r => GetNullableDate(r, "RequestDate"))
                .Where(d => d.HasValue)
                .Select(d => d.Value)
                .GroupBy(d => new { d.Year, d.Month })
                .OrderBy(g => g.Key.Year).ThenBy(g => g.Key.Month)
                .Select(g => g)
                .ToList()
                .ConvertAll(g => g);

            List<string> trendCategories = new List<string>();
            List<int> trendSeries = new List<int>();
            foreach (IGrouping<object, DateTime> monthGrp in monthlyData)
            {
                dynamic key = monthGrp.Key;
                trendCategories.Add(string.Format(CultureInfo.InvariantCulture, "{0:00}/{1}", key.Month, key.Year));
                trendSeries.Add(monthGrp.Count());
            }

            if (trendCategories.Count == 0)
            {
                trendCategories.Add(DateTime.Today.ToString("MM/yyyy", CultureInfo.InvariantCulture));
                trendSeries.Add(0);
            }

            List<int> stackedReturned = new List<int>();
            List<int> stackedBorrowInTerm = new List<int>();
            List<int> stackedOverdue = new List<int>();

            var monthlyGroups = dt.AsEnumerable()
                .Select(r => GetNullableDate(r, "RequestDate"))
                .Where(d => d.HasValue)
                .Select(d => d.Value)
                .GroupBy(d => new { d.Year, d.Month })
                .OrderBy(g => g.Key.Year).ThenBy(g => g.Key.Month)
                .ToList();

            foreach (var monthGrp in monthlyGroups)
            {
                int yy = monthGrp.Key.Year;
                int mm = monthGrp.Key.Month;
                IEnumerable<DataRow> inMonth = dt.AsEnumerable().Where(r =>
                {
                    DateTime? rd = GetNullableDate(r, "RequestDate");
                    return rd.HasValue && rd.Value.Year == yy && rd.Value.Month == mm;
                });
                stackedReturned.Add(inMonth.Count(r => GetBool(r, "IsRealInput")));
                stackedBorrowInTerm.Add(inMonth.Count(r => IsCurrentlyBorrowedNotReturned(r) && !IsOverdueNotReturned(r)));
                stackedOverdue.Add(inMonth.Count(r => IsOverdueNotReturned(r)));
            }

            List<Dictionary<string, object>> heatmapSeries = new List<Dictionary<string, object>>();
            DayOfWeek[] dowOrder = new DayOfWeek[]
            {
                DayOfWeek.Monday, DayOfWeek.Tuesday, DayOfWeek.Wednesday, DayOfWeek.Thursday,
                DayOfWeek.Friday, DayOfWeek.Saturday, DayOfWeek.Sunday
            };
            string[] dowLabels = new string[] { "Thứ 2", "Thứ 3", "Thứ 4", "Thứ 5", "Thứ 6", "Thứ 7", "CN" };
            for (int i = 0; i < dowOrder.Length; i++)
            {
                DayOfWeek dow = dowOrder[i];
                List<Dictionary<string, object>> dataPoints = new List<Dictionary<string, object>>();
                foreach (var monthGrp in monthlyGroups)
                {
                    int yy = monthGrp.Key.Year;
                    int mm = monthGrp.Key.Month;
                    string xLab = string.Format(CultureInfo.InvariantCulture, "{0:00}/{1}", mm, yy);
                    int cnt = dt.AsEnumerable().Count(r =>
                    {
                        DateTime? rd = GetNullableDate(r, "RequestDate");
                        if (!rd.HasValue)
                            return false;
                        return rd.Value.Year == yy && rd.Value.Month == mm && rd.Value.DayOfWeek == dow;
                    });
                    Dictionary<string, object> point = new Dictionary<string, object>();
                    point["x"] = xLab;
                    point["y"] = cnt;
                    dataPoints.Add(point);
                }
                if (dataPoints.Count == 0)
                {
                    Dictionary<string, object> emptyPoint = new Dictionary<string, object>();
                    emptyPoint["x"] = DateTime.Today.ToString("MM/yyyy", CultureInfo.InvariantCulture);
                    emptyPoint["y"] = 0;
                    dataPoints.Add(emptyPoint);
                }
                Dictionary<string, object> seriesItem = new Dictionary<string, object>();
                seriesItem["name"] = dowLabels[i];
                seriesItem["data"] = dataPoints;
                heatmapSeries.Add(seriesItem);
            }

            while (stackedReturned.Count < trendCategories.Count)
            {
                stackedReturned.Add(0);
                stackedBorrowInTerm.Add(0);
                stackedOverdue.Add(0);
            }

            int reviewApproved = dt.AsEnumerable().Count(IsApprovedForStatistics);
            int reviewRejected = dt.AsEnumerable().Count(IsRejectedForStatistics);
            int reviewPending = dt.AsEnumerable().Count(r => !IsApprovedForStatistics(r) && !IsRejectedForStatistics(r));

            var topBooks = dt.AsEnumerable()
                .GroupBy(r => Convert.ToString(r["BookName"], CultureInfo.InvariantCulture))
                .Select(g => new { Name = string.IsNullOrWhiteSpace(g.Key) ? "(Không rõ tên sách)" : g.Key, Count = g.Count() })
                .OrderByDescending(x => x.Count)
                .ThenBy(x => x.Name)
                .Take(7)
                .ToList();

            List<string> topBookCategories = topBooks.Select(x => x.Name).ToList();
            List<int> topBookSeries = topBooks.Select(x => x.Count).ToList();
            if (topBookCategories.Count == 0)
            {
                topBookCategories.Add("Chưa có dữ liệu");
                topBookSeries.Add(0);
            }

            int stateReturned = dt.AsEnumerable().Count(r => GetBool(r, "IsRealInput"));
            int stateBorrowing = dt.AsEnumerable().Count(r => GetBool(r, "IsRealOutput") && !GetBool(r, "IsRealInput"));
            int stateOverdue = dt.AsEnumerable().Count(IsOverdueNotReturned);

            hidTrendCategoriesJson.Value = serializer.Serialize(trendCategories);
            hidTrendSeriesJson.Value = serializer.Serialize(trendSeries);
            hidReviewSeriesJson.Value = serializer.Serialize(new int[] { reviewApproved, reviewRejected, reviewPending });
            hidTopBookCategoriesJson.Value = serializer.Serialize(topBookCategories);
            hidTopBookSeriesJson.Value = serializer.Serialize(topBookSeries);
            hidBorrowStateSeriesJson.Value = serializer.Serialize(new int[] { stateReturned, stateBorrowing, stateOverdue });
            hidStackedReturnedJson.Value = serializer.Serialize(stackedReturned);
            hidStackedBorrowInTermJson.Value = serializer.Serialize(stackedBorrowInTerm);
            hidStackedOverdueJson.Value = serializer.Serialize(stackedOverdue);
            hidHeatmapSeriesJson.Value = serializer.Serialize(heatmapSeries);
        }

        private void BindRangeDescription(DateTime? fromDate, DateTime? toDate)
        {
            if (fromDate.HasValue && toDate.HasValue)
            {
                litRangeDescription.Text = string.Format(
                    CultureInfo.InvariantCulture,
                    "Đang hiển thị thống kê từ <b>{0:dd/MM/yyyy}</b> đến <b>{1:dd/MM/yyyy}</b>.",
                    fromDate.Value, toDate.Value);
                return;
            }

            litRangeDescription.Text = "Đang hiển thị thống kê toàn bộ dữ liệu mượn/trả.";
        }

        private DateTime? ParseDateInput(string value)
        {
            DateTime d;
            if (DateTime.TryParseExact(value, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out d))
                return d;
            return null;
        }

        private static bool IsApprovedForStatistics(DataRow r)
        {
            if (GetBoolStatic(r, "IsRealOutput") || GetBoolStatic(r, "IsRealInput"))
                return true;
            return GetNullableIntStatic(r, "IsReviewed_Request") == 1;
        }

        private static bool IsRejectedForStatistics(DataRow r)
        {
            if (GetBoolStatic(r, "IsRealOutput") || GetBoolStatic(r, "IsRealInput"))
                return false;
            return GetNullableIntStatic(r, "IsReviewed_Request") == 0;
        }

        private static bool IsCurrentlyBorrowedNotReturned(DataRow r)
        {
            return GetBoolStatic(r, "IsRealOutput") && !GetBoolStatic(r, "IsRealInput");
        }

        private static bool IsOverdueNotReturned(DataRow r)
        {
            if (!IsCurrentlyBorrowedNotReturned(r))
                return false;
            DateTime? expired = GetNullableDateStatic(r, "ExpiredDate");
            return expired.HasValue && expired.Value.Date < DateTime.Today;
        }

        private static bool GetBoolStatic(DataRow row, string column)
        {
            object value = row[column];
            if (value == DBNull.Value || value == null)
                return false;
            bool v;
            return bool.TryParse(value.ToString(), out v) && v;
        }

        private static int? GetNullableIntStatic(DataRow row, string column)
        {
            object value = row[column];
            if (value == DBNull.Value || value == null)
                return null;
            if (value is bool)
                return (bool)value ? 1 : 0;
            if (value is byte)
                return (byte)value;
            int result;
            if (int.TryParse(value.ToString(), out result))
                return result;
            return null;
        }

        private static DateTime? GetNullableDateStatic(DataRow row, string column)
        {
            object value = row[column];
            if (value == DBNull.Value || value == null)
                return null;
            DateTime result;
            if (DateTime.TryParse(value.ToString(), out result))
                return result;
            return null;
        }

        private bool GetBool(DataRow row, string column)
        {
            return GetBoolStatic(row, column);
        }

        private DateTime? GetNullableDate(DataRow row, string column)
        {
            return GetNullableDateStatic(row, column);
        }
    }
}

