        private void BindSummary(DataTable dt)
        {
            int total = dt.Rows.Count;
            int approved = dt.AsEnumerable().Count(IsApprovedForStatistics);
            int borrowing = dt.AsEnumerable().Count(IsCurrentlyBorrowedNotReturned);
            int overdue = dt.AsEnumerable().Count(IsOverdueNotReturned);

            litTotalRequest.Text = total.ToString("N0", CultureInfo.InvariantCulture);
            litApproved.Text = approved.ToString("N0", CultureInfo.InvariantCulture);
            litBorrowing.Text = borrowing.ToString("N0", CultureInfo.InvariantCulture);
            litOverdue.Text = overdue.ToString("N0", CultureInfo.InvariantCulture);
        }

        private void BindCharts(DataTable dt)
        {
            JavaScriptSerializer serializer = new JavaScriptSerializer();

            List<IGrouping<object, DateTime>> monthlyData = dt.AsEnumerable()
                .Select(r => GetNullableDate(r, "RequestDate"))
                .Where(d => d.HasValue)
                .Select(d => d.Value)
                .GroupBy(d => (object)new { d.Year, d.Month })
                .OrderBy(g => ((dynamic)g.Key).Year).ThenBy(g => ((dynamic)g.Key).Month)
                .ToList();

            List<string> trendCategories = new List<string>();
            List<int> trendSeries = new List<int>();
            foreach (IGrouping<object, DateTime> grp in monthlyData)
            {
                dynamic key = grp.Key;
                trendCategories.Add(string.Format(CultureInfo.InvariantCulture, "{0:00}/{1}", (int)key.Month, (int)key.Year));
                trendSeries.Add(grp.Count());
            }

            if (trendCategories.Count == 0)
            {
                trendCategories.Add(DateTime.Today.ToString("MM/yyyy", CultureInfo.InvariantCulture));
                trendSeries.Add(0);
            }

            List<int> stackedReturned = new List<int>();
            List<int> stackedBorrowInTerm = new List<int>();
            List<int> stackedOverdue = new List<int>();
            foreach (IGrouping<object, DateTime> monthGrp in monthlyData)
            {
                dynamic key = monthGrp.Key;
                int yy = (int)key.Year;
                int mm = (int)key.Month;
                IEnumerable<DataRow> inMonth = dt.AsEnumerable().Where(r =>
                {
                    DateTime? rd = GetNullableDate(r, "RequestDate");
                    return rd.HasValue && rd.Value.Year == yy && rd.Value.Month == mm;
                });
                stackedReturned.Add(inMonth.Count(r => GetBool(r, "IsRealInput")));
                stackedBorrowInTerm.Add(inMonth.Count(r => IsCurrentlyBorrowedNotReturned(r) && !IsOverdueNotReturned(r)));
                stackedOverdue.Add(inMonth.Count(r => IsOverdueNotReturned(r)));
            }

            List<Dictionary<string, object>> heatmapSeries = new List<Dictionary<string, object>>();
            DayOfWeek[] dowOrder = new DayOfWeek[]
            {
                DayOfWeek.Monday, DayOfWeek.Tuesday, DayOfWeek.Wednesday, DayOfWeek.Thursday,
                DayOfWeek.Friday, DayOfWeek.Saturday, DayOfWeek.Sunday
            };
            string[] dowLabels = new string[] { "Thứ 2", "Thứ 3", "Thứ 4", "Thứ 5", "Thứ 6", "Thứ 7", "CN" };
            for (int i = 0; i < dowOrder.Length; i++)
            {
                DayOfWeek dow = dowOrder[i];
                List<Dictionary<string, object>> dataPoints = new List<Dictionary<string, object>>();
                foreach (IGrouping<object, DateTime> monthGrp in monthlyData)
                {
                    dynamic key = monthGrp.Key;
                    int yy = (int)key.Year;
                    int mm = (int)key.Month;
                    string xLab = string.Format(CultureInfo.InvariantCulture, "{0:00}/{1}", mm, yy);
                    int cnt = dt.AsEnumerable().Count(r =>
                    {
                        DateTime? rd = GetNullableDate(r, "RequestDate");
                        if (!rd.HasValue)
                            return false;
                        return rd.Value.Year == yy && rd.Value.Month == mm && rd.Value.DayOfWeek == dow;
                    });
                    Dictionary<string, object> point = new Dictionary<string, object>();
                    point["x"] = xLab;
                    point["y"] = cnt;
