            int stateOverdue = dt.AsEnumerable().Count(IsOverdueNotReturned);

            hidTrendCategoriesJson.Value = serializer.Serialize(trendCategories);
            hidTrendSeriesJson.Value = serializer.Serialize(trendSeries);
            hidReviewSeriesJson.Value = serializer.Serialize(new int[] { reviewApproved, reviewRejected, reviewPending });
            hidTopBookCategoriesJson.Value = serializer.Serialize(topBookCategories);
            hidTopBookSeriesJson.Value = serializer.Serialize(topBookSeries);
            hidBorrowStateSeriesJson.Value = serializer.Serialize(new int[] { stateReturned, stateBorrowing, stateOverdue });
            hidStackedReturnedJson.Value = serializer.Serialize(stackedReturned);
            hidStackedBorrowInTermJson.Value = serializer.Serialize(stackedBorrowInTerm);
            hidStackedOverdueJson.Value = serializer.Serialize(stackedOverdue);
            hidHeatmapSeriesJson.Value = serializer.Serialize(heatmapSeries);
        }

        private void BindRangeDescription(DateTime? fromDate, DateTime? toDate)
        {
            if (fromDate.HasValue && toDate.HasValue)
            {
                litRangeDescription.Text = string.Format(
                    CultureInfo.InvariantCulture,
                    "Đang hiển thị thống kê từ <b>{0:dd/MM/yyyy}</b> đến <b>{1:dd/MM/yyyy}</b>.",
                    fromDate.Value, toDate.Value);
                return;
            }

            litRangeDescription.Text = "Đang hiển thị thống kê toàn bộ dữ liệu mượn/trả.";
        }

        private DateTime? ParseDateInput(string value)
        {
            DateTime d;
            if (DateTime.TryParseExact(value, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out d))
                return d;
            return null;
        }

        private static bool IsApprovedForStatistics(DataRow r)
        {
            if (GetBoolStatic(r, "IsRealOutput") || GetBoolStatic(r, "IsRealInput"))
                return true;
            return GetNullableIntStatic(r, "IsReviewed_Request") == 1;
        }

        private static bool IsRejectedForStatistics(DataRow r)
        {
            if (GetBoolStatic(r, "IsRealOutput") || GetBoolStatic(r, "IsRealInput"))
                return false;
            return GetNullableIntStatic(r, "IsReviewed_Request") == 0;
        }

        private static bool IsCurrentlyBorrowedNotReturned(DataRow r)
        {
            return GetBoolStatic(r, "IsRealOutput") && !GetBoolStatic(r, "IsRealInput");
        }

        private static bool IsOverdueNotReturned(DataRow r)
        {
            if (!IsCurrentlyBorrowedNotReturned(r))
                return false;
            DateTime? expired = GetNullableDateStatic(r, "ExpiredDate");
            return expired.HasValue && expired.Value.Date < DateTime.Today;
        }

        private static bool GetBoolStatic(DataRow row, string column)
        {
            object value = row[column];
            if (value == DBNull.Value || value == null)
                return false;
            bool v;
            return bool.TryParse(value.ToString(), out v) && v;
        }

        private static int? GetNullableIntStatic(DataRow row, string column)
        {
            object value = row[column];
            if (value == DBNull.Value || value == null)
                return null;
            if (value is bool)
                return (bool)value ? 1 : 0;
            if (value is byte)
                return (byte)value;
            int result;
            if (int.TryParse(value.ToString(), out result))
                return result;
            return null;
        }

        private static DateTime? GetNullableDateStatic(DataRow row, string column)
        {
            object value = row[column];
            if (value == DBNull.Value || value == null)
                return null;
            DateTime result;
            if (DateTime.TryParse(value.ToString(), out result))
                return result;
            return null;
        }

        private bool GetBool(DataRow row, string column)
        {
            return GetBoolStatic(row, column);
        }

        private DateTime? GetNullableDate(DataRow row, string column)
        {
            return GetNullableDateStatic(row, column);
        }
    }
}

